window.AUTH=window.AUTH||{};window.AUTH["17-532"]={"d":"17-532","id":"2018/17-532","n":"Herrera v. Wyoming","briefs":[{"k":"petitioner","label":"Brief of petitioner Clayvin Herrera","date":"2018-09-04","url":"https://www.supremecourt.gov/DocketPDF/17/17-532/62482/20180904113704523_17-532%20Herrera%20Opening%20Merits%20Brief.pdf","side":"pet","n":52},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-09-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-532/63413/20180911212614508_17-532tsacUnitedStates.pdf","side":"us","n":30},{"k":"respondent","label":"Brief of respondent Wyoming","date":"2018-11-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-532/71707/20181113153510005_Respondent%20Herrera%2017-532.pdf","side":"res","n":62},{"k":"reply","label":"Reply of petitioner Clayvin Herrera","date":"2018-12-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-532/76057/20181213130404906_No.%2017-532rb.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-532_q86b.pdf","tr":true,"items":[{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Antoine v. Washington","cite":"420 U.S. 194","y":1975,"id":"1974/73-717","sc":1,"op":2,"sum":"Appellant Indians were convicted of state statutory game violations that had allegedly been committed in an area of a former Indian reservation that the tribe had ceded to the Government by an Agreement made in 1891, later ratified and implemented by Congress, one of whose provisions (Art. 6), relied upon as a defense by appellants, specified that the hunting rights of Indians in common with other persons would not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 45","1":"29","2":"35"}},{"t":"case","label":"Arizona v. California","cite":"530 U.S. 392","y":2000,"id":"1999/8_orig","sc":1,"op":2,"sum":"The Court rejected both grounds for preclusion and remanded the case to a Special Master for a determination on the merits of the outstanding claims for additional water rights associated with disputed Fort Yuma Reservation boundary lands. \"Those claims are the only ones that remain to be decided in Arizona v. California; their resolution will enable the Court to enter a final consolidated decree and bring this case to a close,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"Bobby v. Bies","cite":"556 U.S. 825","y":2009,"id":"2008/08-598","sc":1,"op":4,"ar":2,"sum":"The Court found that the Double Jeopardy Clause did not prevent relitigation of a mental retardation claim because the defendant was never acquitted at trial.","sumSrc":"Oyez","by":{"0":"47, 50","1":"24","2":"30, 32","3":"14, 17, 18"}},{"t":"case","label":"Bravo-Fernandez v. United States","cite":"137 S. Ct. 352","y":2016,"id":"2016/15-537","sc":1,"op":4,"sum":"The Court decided that the Double Jeopardy Clause does not bar retrial when a jury returns an inconsistent verdict of conviction and acquittal and the convictions are later vacated for a completely separate legal error.","sumSrc":"Oyez","by":{"0":"16, 50, 51, 56","3":"22"}},{"t":"case","label":"Choctaw Nation of Indians v. United States","cite":"318 U.S. 423","y":1943,"id":"scdb/1942-161","sc":1,"op":1,"sum":"Explaining that courts “may look beyond the written words to the history of the treaty, the negotiations, and the practical construction adopted by the parties” to determine a treaty’s meaning.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"Comm’r v. Sunnen","cite":"333 U.S. 591","y":1948,"id":"scdb/1947-064","sc":1,"op":3,"sum":"The facts were sufficient to. support a finding by the Tax Court that the taxpayer retained sufficient interest in the royalty contracts and sufficient control overthe amount of income derived therefrom to justify taxing the income as his.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48","3":"17"}},{"t":"case","label":"Confederated Tribes of the Umatilla Indian Reservation v. Maison","cite":"262 F. Supp. 871","y":1966,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp./262/871/","by":{"0":"44","3":"13"}},{"t":"case","label":"Crow Tribe of Indians v. Repsis","cite":"116 S. Ct. 1851","y":1996,"url":"https://www.courtlistener.com/c/S.%20Ct./116/1851/","sc":1,"by":{"0":"12"}},{"t":"case","label":"Crow Tribe of Indians v. Repsis","cite":"73 F.3d 982","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/73/982/","op":10,"sum":"Explaining that “the district court did not reach [the occupation] issue”.","sumSrc":"opinion","by":{"0":"passim","1":"4, 5, 9, 23, 24, 30","2":"passim, 14, 15, 36, 9, 15, 36, 42, 58","3":"2, 15, 16"}},{"t":"case","label":"Crow Tribe of Indians v. Repsis","cite":"866 F. Supp. 520","y":1994,"court":"D. Wyo.","url":"https://www.courtlistener.com/c/F.%20Supp./866/520/","op":5,"by":{"0":"2, 11, 12, 47","2":"14, 15, 27","3":"2"}},{"t":"case","label":"Currier v. Virginia","cite":"138 S. Ct. 2144","y":2018,"id":"2017/16-1348","sc":1,"op":4,"sum":"The Court decided that because Michael Currier consented to a severance of the multiple charges against him, his second trial and resulting conviction, following an acquittal at his first trial, did not violate the double jeopardy clause.","sumSrc":"Oyez","by":{"0":"56","2":"32","3":"24"}},{"t":"case","label":"Hansberry v. Lee","cite":"311 U.S. 32","y":1940,"id":"scdb/1940-006","sc":1,"sum":"Numerous owners of lots in a particular area agreed in writing, each severally with each of the others, that their lots should not be sold to or occupied by Negroes, the effectiveness of the agreement being conditioned, however, upon signing by owners of a specified percentage of the lot frontage. In a case in a state court, tried upon an agreed statement of facts, in which it was stipulated (erroneously) that this …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Hurd v. District of Columbia","cite":"864 F.3d 671","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/864/671/","sum":"Noting the “general view of courts and commentators” that the “full and fair opportunity” requirement is “among the most critical guarantees of fairness” in applying issue preclusion.","sumSrc":"brief:0","by":{"0":"52"}},{"t":"case","label":"Jones v. Meehan","cite":"175 U.S. 1","y":1899,"id":"scdb/1899-001","sc":1,"sum":"A good title to parts of the lands of an Indian tribe may be granted to individuals by a treaty between „the United States and the tribe, without any act of Congress, or any patent from the Executive authority of the United States. The question in every case is whether the terms of the treaty are such as to manifest the intention of the parties to make a present grant to the persons named.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22","2":"39"}},{"t":"case","label":"Kircher v. Putnam Funds Tr.","cite":"547 U.S. 633","y":2006,"id":"2005/05-409","sc":1,"sum":"The Supreme Court unanimously held that the district court's decision had been jurisdictional and that the appeals court's review was therefore barred by 1447(d).","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Limbach v. Hooven & Allison Co.","cite":"466 U.S. 353","y":1984,"id":"1983/83-96","sc":1,"op":4,"ar":3,"sum":"Respondent manufacturer of cordage products, in filing its Ohio ad valorem personal property tax returns for 1976 and 1977, deducted from the total value of its inventory the value of imported fibers that were stored in their original packages for future use in the manufacturing process. In taking this deduction, respondent relied on Hooven & Allison Co. v. Evatt, 324 U. S. 652 (Hooven I), a case involving the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","3":"15, 16, 17"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"134 S. Ct. 2024","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"0":"55","2":"54"}},{"t":"case","label":"Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"526 U.S. 172","y":1999,"id":"1998/97-1337","sc":1,"op":27,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that the Mille Lacs Band of Chippewa Indians does have usufructuary rights that were guaranteed to them by the 1837 treaty.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Montana v. United States","cite":"440 U.S. 147","y":1979,"id":"1978/77-1134","sc":1,"op":4,"sum":"The United States is collaterally estopped from challenging the prior judgment of the Montana Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","2":"23, 31, 32","3":"17, 18"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"op":3,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 5, 7, 8","1":"1, 2, 3, 11","2":"4, 5, 43, 54"}},{"t":"case","label":"N.W. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"0":"54","3":"23"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"op":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Parklane Hosiery Co., Inc. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Richards v. Jefferson Cty.","cite":"517 U.S. 793","y":1996,"id":"1995/95-386","sc":1,"sum":"Authored by Justice John Paul Stevens, the Court ruled that because Richards and others received neither notice of, nor sufficient representation in, the Bedingfield litigation, that adjudication, as a matter of federal due process, may not bind them and thus cannot bar them from challenging an allegedly unconstitutional deprivation of their property.","sumSrc":"Oyez","by":{"0":"55","2":"24"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"50","2":"22"}},{"t":"case","label":"Seufert Bros. Co. v. United States","cite":"249 U.S. 194","y":1919,"id":"scdb/1918-190","sc":1,"sum":"The right secured to the Yakima Indians, through their treaty of June 9, 1855, Art. Ill, 12 Stat. 25, of taking fish at all usual and accustomed places, in common with citizens of the United States, and of erecting temporary buildings for curing them,.extends to places in Oregon on the south side of the Columbia River, where these Indians habitually fished before and since the treaty, even though beyond the limits …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23, 36"}},{"t":"case","label":"Simpson v. Florida","cite":"403 U.S. 384","y":1971,"id":"1970/1267","sc":1,"sum":"As stated in Ashe, supra, \"mutuality\" is not an ingredient of the collateral estoppel rule imposed on the States by the Fifth and Fourteenth Amendments; and unless the jury verdict in the second trial \"could have [been] grounded... upon an issue other than that which the defendant seeks to foreclose from consideration\" the double jeopardy provision vitiates petitioner's conviction. Certiorari granted; 237 So. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"56","3":"24"}},{"t":"case","label":"Smith v. Bayer Corp.","cite":"564 U.S. 299","y":2011,"id":"2010/09-1205","sc":1,"sum":"The Court held that the federal court exceeded its authority under the relitigation exception to the Anti-Injunction Act when it prevented a group of plaintiffs from proceeding with a class-action lawsuit over a cholesterol-lowering drug.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"South Dakota v. Bourland","cite":"508 U.S. 679","y":1993,"id":"1992/91-2051","sc":1,"sum":"Congress, in the Flood Control and Cheyenne River Acts, abrogated the Tribe's rights under the Fort Laramie Treaty to regulate non-Indian hunting and fishing on lands taken by the United States for construction of the Oahe Dam and Reservoir.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 25","2":"50"}},{"t":"case","label":"Standefer v. United States","cite":"447 U.S. 10","y":1980,"id":"1979/79-383","sc":1,"op":1,"sum":"A defendant accused of aiding and abetting in the commission of a federal offense may properly be convicted despite the prior acquittal of the alleged actual perpetrator of the offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"State v. Arthur","cite":"261 P.2d 135","y":1953,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/261/135/","by":{"0":"44","1":"20","3":"13"}},{"t":"case","label":"State v. Buchanan","cite":"978 P.2d 1070","y":1999,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/978/1070/","op":1,"by":{"0":"30","1":"20","3":"13"}},{"t":"case","label":"State v. Miller","cite":"689 P.2d 81","y":1984,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/689/81/","by":{"0":"43"}},{"t":"case","label":"State v. Stasso","cite":"563 P.2d 562","y":1977,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/563/562/","by":{"0":"43","3":"13"}},{"t":"case","label":"State v. Tinno","cite":"497 P.2d 1386","y":1972,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/497/1386/","by":{"0":"43","1":"20"}},{"t":"case","label":"Swim v. Bergland","cite":"696 F.2d 712","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/696/712/","by":{"0":"39"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"op":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"passim","1":"23","2":"24","3":"24"}},{"t":"case","label":"United States v. Gallardo-Mendez","cite":"150 F.3d 1240","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/150/1240/","by":{"0":"57","2":"34"}},{"t":"case","label":"United States v. Harnage","cite":"976 F.2d 633","y":1992,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/976/633/","by":{"0":"57","2":"34"}},{"t":"case","label":"United States v. Hicks","cite":"587 F. Supp. 1162","y":1984,"court":"W.D. Wash.","url":"https://www.courtlistener.com/c/F.%20Supp./587/1162/","ar":3,"by":{"0":"14"}},{"t":"case","label":"United States v. Mendoza","cite":"464 U.S. 154","y":1984,"id":"1983/82-849","sc":1,"sum":"The United States may not be collaterally estopped on an issue such as the one involved here, adjudicated against it in an earlier lawsuit brought by a different party.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"United States v. Pelullo","cite":"14 F.3d 881","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/14/881/","sum":"Rejecting issue preclusion for an element of the crime.","sumSrc":"brief:2","by":{"0":"57","2":"34"}},{"t":"case","label":"United States v. Stauffer Chem. Co.","cite":"464 U.S. 165","y":1984,"id":"1983/82-1448","sc":1,"ar":1,"sum":"The Court held that the EPA's case against Stauffer was precluded by the doctrine of collateral estoppell.","sumSrc":"Oyez","by":{"0":"50","2":"25"}},{"t":"case","label":"Ward v. Race Horse","cite":"163 U.S. 504","y":1896,"id":"scdb/1895-261","sc":1,"op":64,"ar":41,"sum":"The provision in the treaty of February 24,1869, with the Bannock Indians, whose reservation was within the limits of what is now the State of Wyoming, that “they shall have the right to hunt upon the unoccupied lands of the United States so long as game may be found thereon,” etc., does not give them the right to exercise this privilege within the limits of that State in violation of its laws.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11, 12, 27, 29","1":"5, 9, 16, 17, 18, 22","2":"passim","3":"3, 4, 14"}},{"t":"case","label":"Wash. Game Dep’t v. Puyallup Tribe","cite":"414 U.S. 44","y":1973,"id":"1973/72-481","sc":1,"sum":"Commercial net fishing by Puyallup Indians, fofiwhichthe Indians have treaty protection, Puyallup Tribe v. Dept. of Game, 391 U. S. 392, forecloses the bar agaifist net fishing of steelhead trout imposed by Washington State Game Department's regulation, ivhich discriminates against the Puyallups, and as long as steelhead fishing is permitted, the regulation must achieve an accommodation between the Puyallups' …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Washington v. Wash. State Commercial Passenger Fishing Vessel Ass’n","cite":"443 U.S. 658","y":1979,"id":"1978/77-983","sc":1,"op":5,"sum":"In 1854 and 1855, the United States entered into a series of treaties with certain Indian tribes whereby the Indians relinquished their interest in certain lands in what is now the State of Washington in exchange for monetary payments, certain relatively small parcels of land reserved for their exclusive use, and other guarantees, including protection of their \"right of taking fish at usual and accustomed grounds …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 34, 44","1":"12, 27"}},{"t":"case","label":"Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"usc","label":"16 U.S.C. § 256b","url":"https://www.law.cornell.edu/uscode/text/16/256b","by":{"0":"14"}},{"t":"usc","label":"43 U.S.C. § 1732","url":"https://www.law.cornell.edu/uscode/text/43/1732","subs":["(b)"],"stext":{"head":"§1732. Management of use, occupancy, and development of public lands","paras":[[0,"(a) Multiple use and sustained yield requirements applicable; exception"],[0,"The Secretary shall manage the public lands under principles of multiple use and sustained yield, in accordance with the land use plans developed by him under section 1712 of this title when they are available, except that where a tract of such public land has been dedicated to specific uses according to any other provisions of law it shall be managed in accordance with such law."],[0,"(b) Easements, permits, etc., for utilization through habitation, cultivation, and development of small trade or manufacturing concerns; applicable statutory requirements"],[0,"In managing the public lands, the Secretary shall, subject to this Act and other applicable law and under such terms and conditions as are consistent with such law, regulate, through easements, permits, leases, licenses, published rules, or other instruments as the Secretary deems appropriate, the use, occupancy, and development of the public lands, including, but not limited to, long-term leases to permit individuals to utilize public lands for habitation, cultivation, and the development of small trade or manufacturing concerns: Provided, That unless otherwise provided for by law, the Secretary may permit Federal departments and agencies to use, occupy, and develop public lands only through rights-of-way under section 1767 of this title, withdrawals under section 1714 of this title, and, where the proposed use and development are similar or closely related to the programs of the Secretary for the public lands involved, cooperative agreements under section 1737(b) of this title: Provided further, That nothing in this Act shall be construed as authorizing the Secretary concerned to require Federal permits to hunt and fish on public lands or on lands in the National Forest System and adjacent waters or as enlarging or diminishing the responsibility and authority of the States for management of fish and resident wildlife. However, the Secretary concerned may designate areas of public land and of lands in the National Forest System where, and establish periods when, no hunting or fishing will be permitted for reasons of public safety, administration, or compliance with provisions of applicable law. Except in emergencies, any regulations of the Secretary concerned relating to hunting and fishing pursuant to this section shall be put into effect only after consultation with the appropriate State fish and game department. Nothing in this Act shall modify or change any provision of Federal law relating to migratory birds or to endangered or threatened species. Except as provided in section 1744, section 1782, and subsection (f) of section 1781 of this title and in the last sentence of this paragraph, no provision of this section or any other section of this Act shall in any way amend the Mining Law of 1872 or impair the rights of any locators or claims under that Act, including, but not limited to, rights of ingress and egress. In managing the public lands the Secretary shall, by regulation or otherwise, take any action necessary to prevent unnecessary or undue degradation of the lands."],[0,"(c) Revocation or suspension provision in instrument authorizing use, occupancy or development; violation of provision; procedure applicable"],[0,"The Secretary shall insert in any instrument providing for the use, occupancy, or development of the public lands a provision authorizing revocation or suspension, after notice and hearing, of such instrument upon a final administrative finding of a violation of any term or condition of the instrument, including, but not limited to, terms and conditions requiring compliance with regulations under Acts applicable to the public lands and compliance with applicable State or Federal air or water quality standard or implementation plan: Provided, That such violation occurred on public lands covered by such instrument and occurred in connection with the exercise of rights and privileges granted by it: Provided further, That the Secretary shall terminate any such suspension no later than the date upon which he determines the cause of said violation has been rectified: Provided further, That the Secretary may order an immediate temporary suspension prior to a hearing or final administrative finding if he determines that such a suspension is necessary to protect health or safety or the environment: Provided further, That, where other applicable law contains specific provisions for suspension, revocation, or cancellation of a permit, license, or other authorization to use, occupy, or develop the public lands, the specific provisions of such law shall prevail."],[0,"(d) Authorization to utilize certain public lands in Alaska for military purposes"],[0,"(1) The Secretary of the Interior, after consultation with the Governor of Alaska, may issue to the Secretary of Defense or to the Secretary of a military department within the Department of Defense or to the Commandant of the Coast Guard a nonrenewable general authorization to utilize public lands in Alaska (other than within a conservation system unit or the Steese National Conservation Area or the White Mountains National Recreation Area) for purposes of military maneuvering, military training, or equipment testing not involving artillery firing, aerial or other gunnery, or other use of live ammunition or ordnance."],[0,"(2) Use of public lands pursuant to a general authorization under this subsection shall be limited to areas where such use would not be inconsistent with the plans prepared pursuant to section 1712 of this title. Each such use shall be subject to a requirement that the using department shall be responsible for any necessary cleanup and decontamination of the lands used, and to such other terms and conditions (including but not limited to restrictions on use of off-road or all-terrain vehicles) as the Secretary of the Interior may require to—"],[1,"(A) minimize adverse impacts on the natural, environmental, scientific, cultural, and other resources and values (including fish and wildlife habitat) of the public lands involved; and"],[1,"(B) minimize the period and method of such use and the interference with or restrictions on other uses of the public lands involved."],[0,"(3)(A) A general authorization issued pursuant to this subsection shall not be for a term of more than three years and shall be revoked in whole or in part, as the Secretary of the Interior finds necessary, prior to the end of such term upon a determination by the Secretary of the Interior that there has been a failure to comply with its terms and conditions or that activities pursuant to such an authorization have had or might have a significant adverse impact on the resources or values of the affected lands."],[0,"(B) Each specific use of a particular area of public lands pursuant to a general authorization under this subsection shall be subject to specific authorization by the Secretary and to appropriate terms and conditions, including such as are described in paragraph (2) of this subsection."],[0,"(4) Issuance of a general authorization pursuant to this subsection shall be subject to the provisions of section 1712(f) of this title, section 3120 of title 16, and all other applicable provisions of law. The Secretary of a military department (or the Commandant of the Coast Guard) requesting such authorization shall reimburse the Secretary of the Interior for the costs of implementing this paragraph. An authorization pursuant to this subsection shall not authorize the construction of permanent structures or facilities on the public lands."],[0,"(5) To the extent that public safety may require closure to public use of any portion of the public lands covered by an authorization issued pursuant to this subsection, the Secretary of the military Department concerned or the Commandant of the Coast Guard shall take appropriate steps to notify the public concerning such closure and to provide appropriate warnings of risks to public safety."],[0,"(6) For purposes of this subsection, the term \"conservation system unit\" has the same meaning as specified in section 3102 of title 16."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1732?type=usc&year=mostrecent&link-type=html"},"head":"§1732. Management of use, occupancy, and development of public lands","tname":"Public Lands","by":{"0":"14","1":"28"}},{"t":"law","label":"Pub. L. No. 103-444","url":"https://www.govinfo.gov/link/statute/108/4632","by":{"0":"8"}},{"t":"case","label":"Blackfeather v. United States","cite":"190 U.S. 368","y":1903,"id":"scdb/1902-168","sc":1,"sum":"The moral obligations Of the government towards the Indians are for Congress alone to recognize, and the courts can exercise only such jurisdiction over the subject as Congress may confer upon them.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"op":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Hebah v. United States","cite":"428 F.2d 1334","y":1970,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/428/1334/","by":{"1":"23"}},{"t":"case","label":"Hinderlider v. La Plata River & Cherry Creek Ditch Co.","cite":"304 U.S. 92","y":1938,"id":"scdb/1937-042","sc":1,"op":1,"sum":"1. The water of an interstate stream, used beneficially in each of the two States through which it flows, must be equitably apportioned between the two. P. 101. The claim that on interstate streams the upper State has such ownership or control of the whole stream as entitles it to divert all the.water, regardless of any injury or prejudice to the lower State, has been consistently denied by this Court. P. 102.--'. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24","2":"25"}},{"t":"case","label":"Holcomb v. Confederated Tribes of the Umatilla Indian Reservation","cite":"382 F.2d 1013","y":1967,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/382/1013/","by":{"1":"20"}},{"t":"case","label":"Leatherman v. Tarrant Cnty. Narcotics Intelligence & Coordination Unit","cite":"507 U.S. 163","y":1993,"id":"1992/91-1657","sc":1,"sum":"L A federal court may not apply a \"heightened pleading standard\"more stringent than the usual pleading requirements of Federal Rule of Civil Procedure 8(a)-in civil rights cases alleging municipal liability under § 1983. First, the heightened standard cannot be justified on the ground that a more relaxed pleading standard would eviscerate municipalities' immunity from suit by subjecting them to expensive and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Shoshone-Bannock Tribes v. Fish & Game Comm’n","cite":"42 F.3d 1278","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/42/1278/","op":12,"ar":4,"by":{"1":"20"}},{"t":"case","label":"State v. Cutler","cite":"708 P.2d 853","y":1985,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/708/853/","op":1,"sum":"Stating that the Federal Government may not be foreclosed from using land in such a way that the Indians would have considered it occupied.","sumSrc":"opinion","by":{"1":"28","2":"50, 52, 57"}},{"t":"case","label":"Tulee v. Washington","cite":"315 U.S. 681","y":1942,"id":"scdb/1941-142","sc":1,"sum":"Under the provision of the treaty of May 29, 1855, with the Yakima Indians, reserving to the members of the tribe the right to take fish \"at all usual and accustomed places, in common with the citizens\" of Washington Territory, the State of Washington has the power to impose on the Indians equally with others such restrictions of a purely regulatory nature concerning the time and manner of fishing outside the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"United States v. Dion","cite":"476 U.S. 734","y":1986,"id":"1985/85-246","sc":1,"op":3,"sum":"The Court of Appeals erred in recognizing respondent's treaty defense to the prosecutions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"35"}},{"t":"case","label":"United States v. Winans","cite":"198 U.S. 371","y":1905,"id":"scdb/1904-073","sc":1,"sum":"This court will construe a treaty with Indians as they understood it and as justice and reason demand.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20","2":"14, 16"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"28"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"1":"3, 25"}},{"t":"const","label":"Article IV","clauses":[["full-faith-credit","Full Faith and Credit Clause"],["privileges-immunities-iv","Privileges and Immunities Clause"],["fugitive-slave","Fugitive Slave Clause"],["property-clause","Territory and Property Clause"],["guarantee","Guarantee Clause"]],"by":{"1":"3, 10, 11, 12, 25, 5, 16"}},{"t":"usc","label":"16 U.S.C. § 475","url":"https://www.law.cornell.edu/uscode/text/16/475","by":{"1":"4"}},{"t":"usc","label":"16 U.S.C. § 528","url":"https://www.law.cornell.edu/uscode/text/16/528","by":{"1":"4"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"ASARCO, Inc. v. Kadish","cite":"490 U.S. 605","y":1989,"id":"1988/87-1661","sc":1,"sum":"The judgment is affirmed. 155 Ariz. 484, 747 P. 2d 1183, affirmed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts I, II-A, II-B-2, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Ashe v. Swenson","cite":"397 U.S. 436","y":1970,"id":"1969/57","sc":1,"sum":"Three or four men robbed six poker players. Petitioner was separately charged with having robbed one of the players, Knight, who along with three others testified for the prosecution that each had been robbed. The State's evidence that petitioner had been one of the robbers was weak. The defense offered no testimony. The trial judge instructed the jury that if it found that petitioner participated in the robbery, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Buford v. Houtz","cite":"133 U.S. 320","y":1890,"id":"scdb/1889-116","sc":1,"sum":"There is an implied license, growing out of the custom of nearly one hundred years, that the public lands of the United States, especially those in which the native grasses are adapted to the growth and fattening of domestic animals, shall be free to the people who seek to use them, where they are left open and unenclosed, and no act of the government forbids their use.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Cal. Coastal Comm’n v. Granite Rock Co.","cite":"480 U.S. 572","y":1987,"id":"1986/85-1200","sc":1,"ar":1,"sum":"The Mining Act of 1872 authorizes a private citizen to enter federal lands to explore for mineral deposits, to perfect a mining claim, and to secure a patent to the land by complying with the requirements of the Act and regulations promulgated thereunder. Appellee Granite Rock Co. holds unpatented mining claims on federally owned lands in a national forest located in California. In accordance with federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"58"}},{"t":"case","label":"Cherokee Nation v. Georgia","cite":"30 U.S. 1","y":1831,"id":"scdb/1831-041","sc":1,"sum":"Status of Indian nations.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Crow Tribe of Indians v. United States","cite":"284 F.2d 361","y":1960,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/284/361/","by":{"2":"4, 5"}},{"t":"case","label":"Duckett v. State","cite":"966 P.2d 941","y":1998,"court":"Wyo.","url":"https://www.courtlistener.com/c/P.2d/966/941/","op":1,"by":{"2":"35"}},{"t":"case","label":"Hagen v. Utah","cite":"510 U.S. 399","y":1994,"id":"1993/92-6281","sc":1,"sum":"Petitioner, an Indian, was charged in Utah state court with distribution of a controlled substance in the town of Myton, which lies within the original boundaries of the Uintah Indian Reservation on land that was opened to non-Indian settlement in 1905. The trial court rejected petitioner's claim that it lacked. jurisdiction over him because he was an Indian and the crime had been committed in \"Indian country,\" see …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41, 56"}},{"t":"case","label":"Hilton v. S.C. Pub. Rys. Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"sum":"FELA creates a cause of action against a state-owned railroad, enforceable in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Hutton v. Frisbie","cite":"37 Cal. 475","y":1869,"court":"Cal.","url":"https://www.courtlistener.com/c/Cal./37/475/","by":{"2":"40"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"op":25,"sum":"Authored by Justice David H. Souter, the Court ruled that the federal carjacking law established three separate offenses by the specification of elements, each of which must be charged by indictment, proved beyond a reasonable doubt, and submitted to a jury for its verdict.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"1"}},{"t":"case","label":"Mille Lacs Band of Chippewa Indians v. Minnesota","cite":"124 F.3d 904","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/124/904/","by":{"2":"48"}},{"t":"case","label":"Moses v. Dep’t of Corr.","cite":"736 N.W.2d 269","y":2007,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/736/269/","by":{"2":"25"}},{"t":"case","label":"Or. Dep’t of Fish and Wildlife v. Klamath Indians Tribe","cite":"473 U.S. 753","y":1993,"id":"1984/83-2148","sc":1,"sum":"In light of the terms of the 1901 Agreement and the 1864 Treaty, and certain other events in the Tribe's history, the Tribe's exclusive right to hunt and fish on the lands reserved to the Tribe by the 1864 Treaty did not survive as a special right to be free of state regulation in the ceded lands that were outside the reservation after the 1901 Agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"case","label":"Patterson v. New York","cite":"432 U.S. 197","y":1977,"id":"1976/75-1861","sc":1,"sum":"New York law requiring that the defendant in a prosecution for seconddegree murder prove by a preponderance of the evidence the affirmative defense of extreme emotional disturbance in order to reduce the crime to manslaughter held not to violate the Due Process Clause of the Fourteenth Amendment. Mullaney v. Wilbur, 421 U. S. 684, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"Shoshone Tribe of Indians v. United States","cite":"299 U.S. 476","y":1937,"id":"scdb/1936-163","sc":1,"sum":"(1) That the jurisdictional Act is not an exercise of eminent domain, although it provides that a recovery under it shall be in full settlement and shall annul the claim of the Shoshones. Consequently the date of that Act is not the time as of which the property taken should be valued in assessing compensation. P. 492. (2) Neither are the damages to be measured as of a date (Aug. 13, 1891) when the Commissioner of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"sum":"The Court noted that antitrust cases are typically decided by weighing the costs and benefits of restrictions in each individual case instead of by per se rules as in Albrecht . Also, there was significant precedent contradicting the assertion that all trade restrictions are illegal, and there was evidence that the effects of price-fixing are not as detrimental as the Court thought at the time of Albrecht .","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"United States v. Choctaw Nation","cite":"179 U.S. 494","y":1900,"id":"scdb/1900-051","sc":1,"sum":"On the 4th day of June, 1891, the United States and the Wichita and Affiliated Bands of Indians entered into an agreement whereby the Indians ceded to the United States a tract of land which is described in the Opinion of the court in this case, and the United States agreed in consideration thereof that out of the territory so ceded there should be allotted to each member of the Wichita and Affiliated Bands of …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"United States v. Mazurie","cite":"419 U.S. 544","y":1975,"id":"1974/73-1018","sc":1,"sum":"Respondents, who operated a bar on non-Indian land on the outskirts of an unincorporated village within the Wind River Reservation and who had been denied a tribal liquor license by the Wind River Tribes pursuant to their option under 18 U. S. C. § 1161 to regulate the introduction of liquor into Indian country, were convicted at a nonjury trial of introducing spirituous beverages into Indian country in violation of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"United States v. Moser","cite":"266 U.S. 236","y":1924,"id":"scdb/1924-003","sc":1,"sum":"1. While the doctrine of res judicata does not apply to unmixed questions of law, a fact or right distinctly adjudged cannot be disputed in a subsequent action between the same parties, even upon another demand and though the original determination was reached upon an erroneous view or application of the law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31, 32","3":"18"}},{"t":"case","label":"United States v. N. Pac. Ry. Co.","cite":"311 U.S. 317","y":1940,"id":"scdb/1940-003","sc":1,"sum":"1. In a suit under the Act of June 25, 1929, for an accounting, etc.. between the United States and the Northern Pacific Railway Company, with respect to the land grants made by the United States to that, company's preaecessor, decision on the following propositions of the Government, each. advanced as a defense to 311 U. S. any relief for the company, are reserved, eight Justices who heard the case being equally …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"United States v. New Mexico","cite":"438 U.S. 696","y":1978,"id":"1977/77-510","sc":1,"sum":"The United States, in setting aside the Gila National Forest from other public lands, held to have reserved the use of water out of the Rio Mimbres only where necessary to preserve the timber in the forest or to secure favorable water flows, and hence not to have a reserved right for aesthetic, recreational, wildlife-preservation, and stockwatering purposes. That this was Congress' intent is revealed in the limited …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"59"}},{"t":"case","label":"United States v. Shoshone Tribe of Indians","cite":"304 U.S. 111","y":1938,"id":"scdb/1937-060","sc":1,"sum":"Assistant. Attorney General McFarland, with whom Solicitor General Jackson and Mr. Oscar Provost were on the brief, for the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"8, 49"}},{"t":"case","label":"United States v. Thomas","cite":"151 U.S. 577","y":1894,"id":"scdb/1893-133","sc":1,"sum":"Under the act of March 3, 1885, c. 341, 23 Stat. 362,. the Federal.court in Wisconsin has jurisdiction to try an Indian charged with murdering another Indian within the limits of section 16 in a township in that State which is embraced within and forms part of the La Court Oreilles reservation for the Chippewa Indians.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"United States v. Title Ins. & Tr. Co.","cite":"265 U.S. 472","y":1924,"id":"scdb/1923-181","sc":1,"sum":"1. Where there are two grounds upon either of -which an appellate court may rest-its decision, and it adopts both, the ruling on neither is obiter dictum, but each is the judgment of the court, and of equal validity.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37","3":"21"}},{"t":"case","label":"Ute Indian Tribe of the Uintah & Ouray Reservation v. Utah","cite":"790 F.3d 1000","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/790/1000/","by":{"2":"30, 33, 34","3":"19"}},{"t":"usc","label":"16 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/16/553","by":{"2":"59"}},{"t":"reg","label":"36 C.F.R. § 241.2","url":"https://www.ecfr.gov/current/title-36/section-241.2","by":{"2":"58"}},{"t":"reg","label":"36 C.F.R. § 241.3","url":"https://www.ecfr.gov/current/title-36/section-241.3","subs":["(b)"],"by":{"2":"58"}},{"t":"reg","label":"36 C.F.R. § 261.10","url":"https://www.ecfr.gov/current/title-36/section-261.10","subs":["(d)(1)"],"by":{"2":"59","3":"10"}},{"t":"reg","label":"National Forest System Prohibitions, 42 Fed. Reg. 2956","url":"https://www.govinfo.gov/link/fr/42/2956","by":{"2":"59"}},{"t":"reg","label":"for the Administration and En- forcement of Laws Relating to Wildlife, 6 Fed. Reg. 1987","url":"https://www.govinfo.gov/link/fr/6/1987","by":{"2":"59"}},{"t":"case","label":"Comair Rotron, Inc. v. Nippon Densan Corp.","cite":"49 F.3d 1535","y":1995,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/49/1535/","by":{"3":"22"}},{"t":"case","label":"Johnson v. Perdue","cite":"862 F.3d 712","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/862/712/","by":{"3":"18"}},{"t":"case","label":"Peabody Coal Co. v. Spese","cite":"117 F.3d 1001","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/1001/","by":{"3":"22"}},{"t":"case","label":"Postlewaite v. McGraw-Hill","cite":"333 F.3d 42","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/333/42/","by":{"3":"22"}},{"t":"case","label":"Ritter v. Mount St. Mary’s Coll.","cite":"814 F.2d 986","y":1987,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/814/986/","by":{"3":"22"}},{"t":"case","label":"SFM Holdings, Ltd. v. Banc of Am. Secs., LLC","cite":"764 F.3d 1327","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/764/1327/","by":{"3":"22"}},{"t":"case","label":"Stan Lee Media, Inc. v. Walt Disney Co.","cite":"774 F.3d 1292","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/1292/","by":{"3":"22"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Winters v. Diamond Shamrock Chem. Co.","cite":"149 F.3d 387","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/149/387/","op":2,"sum":"Observing that the “availability of review is of paramount importance to the issue of preclusion”.","sumSrc":"brief:3","by":{"3":"22"}},{"t":"case","label":"Pet. for Writ of Cert., Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"1998 WL 34081059","y":1998,"court":"U.S. Feb. 17","by":{"3":"16"}}]};